import { Component, EventEmitter, OnInit, Output } from '@angular/core';
import { RecipeService } from '../../services/recipe.service';
import { Recipe } from '../../models/recipe.model';

@Component({
  selector: 'app-recipe-grid',
  templateUrl: './recipe-grid.component.html',
  styleUrls: ['./recipe-grid.component.css']
})
export class RecipeGridComponent implements OnInit {
  @Output() recipeClick = new EventEmitter<number>();

  recipes: Recipe[] = [];
  loading = true;
  error: string | null = null;

  backendUrl = 'http://localhost:8000';

  constructor(private recipeService: RecipeService) {}

  ngOnInit() {
    this.loadRecipes();
  }

  loadRecipes() {
    this.loading = true;
    this.recipeService.getRecipes().subscribe({
      next: (response) => {
        if (response.success && response.data) {
          this.recipes = response.data.recipes;
        }
        this.loading = false;
      },
      error: (error) => {
        console.error('Fehler beim Laden der Rezepte:', error);
        this.error = 'Rezepte konnten nicht geladen werden. Verwende Mock-Daten.';
        this.loadMockRecipes();
        this.loading = false;
      }
    });
  }

  loadMockRecipes() {
    // Mock-Daten für Demonstration
    this.recipes = [
      {
        id: 1,
        title: 'Pasta Carbonara',
        description: 'Klassische italienische Pasta mit cremiger Sauce',
        image: 'https://images.unsplash.com/photo-1612874742237-6526221588e3?w=800',
        cookTime: '30 Min',
        difficulty: 'Mittel',
        author: 'Maria Rossi',
        authorId: 1,
        authorAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Maria',
        averageRating: 4.5,
        ratingCount: 12
      },
      {
        id: 2,
        title: 'Thai Green Curry',
        description: 'Würziges grünes Curry mit Kokosmilch und Gemüse',
        image: 'https://images.unsplash.com/photo-1455619452474-d2be8b1e70cd?w=800',
        cookTime: '45 Min',
        difficulty: 'Schwer',
        author: 'Chen Wei',
        authorId: 2,
        authorAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=Chen',
        averageRating: 4.8,
        ratingCount: 24
      },
      {
        id: 3,
        title: 'Caesar Salad',
        description: 'Frischer Salat mit Parmesan und hausgemachtem Dressing',
        image: 'https://images.unsplash.com/photo-1546793665-c74683f339c1?w=800',
        cookTime: '15 Min',
        difficulty: 'Einfach',
        author: 'John Smith',
        authorId: 3,
        authorAvatar: 'https://api.dicebear.com/7.x/avataaars/svg?seed=John',
        averageRating: 4.2,
        ratingCount: 8
      }
    ];
  }

  onRecipeClick(recipeId: number) {
    this.recipeClick.emit(recipeId);
  }

  getDifficultyColor(difficulty: string): string {
    switch (difficulty) {
      case 'Einfach': return 'bg-green-100 text-green-800';
      case 'Mittel': return 'bg-yellow-100 text-yellow-800';
      case 'Schwer': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  }

  getStarArray(rating: number): number[] {
    return Array(5).fill(0).map((_, i) => i < Math.round(rating) ? 1 : 0);
  }
}
<div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
  <h2 class="text-3xl text-gray-900 mb-8">Beliebte Rezepte</h2>

  <!-- Loading State -->
  <div *ngIf="loading" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
    <div *ngFor="let i of [1,2,3,4,5,6]" class="bg-white rounded-lg shadow-md overflow-hidden animate-pulse">
      <div class="h-48 bg-gray-300"></div>
      <div class="p-6">
        <div class="h-6 bg-gray-300 rounded mb-4"></div>
        <div class="h-4 bg-gray-300 rounded mb-2"></div>
        <div class="h-4 bg-gray-300 rounded w-2/3"></div>
      </div>
    </div>
  </div>

  <!-- Error State -->
  <div *ngIf="error" class="bg-yellow-50 border border-yellow-200 rounded-lg p-4 mb-6">
    <p class="text-yellow-800">{{ error }}</p>
  </div>

  <!-- Recipe Grid -->
  <div *ngIf="!loading" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
    <div 
      *ngFor="let recipe of recipes"
      (click)="onRecipeClick(recipe.id)"
      class="bg-white rounded-lg shadow-md overflow-hidden cursor-pointer transform transition-transform hover:scale-105 hover:shadow-xl">

      <!-- Recipe Image -->
      <div class="relative h-48 overflow-hidden">
        <img 
          [src]="recipe.image" 
          [alt]="recipe.title"
          class="w-full h-full object-cover">

        <!-- Difficulty Badge -->
        <span [ngClass]="getDifficultyColor(recipe.difficulty)" 
              class="absolute top-3 right-3 px-3 py-1 rounded-full text-xs">
          {{ recipe.difficulty }}
        </span>
      </div>

      <!-- Recipe Info -->
      <div class="p-6">
        <h3 class="text-xl text-gray-900 mb-2">{{ recipe.title }}</h3>
        <p class="text-gray-600 mb-4 line-clamp-2">{{ recipe.description }}</p>

        <!-- Meta Info -->
        <div class="flex items-center justify-between mb-4">
          <div class="flex items-center gap-2 text-gray-500">
            <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" 
                    d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path>
            </svg>
            <span class="text-sm">{{ recipe.cookTime }}</span>
          </div>

          <!-- Rating -->
          <div class="flex items-center gap-1">
            <svg 
              *ngFor="let filled of getStarArray(recipe.averageRating)"
              class="w-4 h-4" 
              [ngClass]="filled ? 'text-yellow-400' : 'text-gray-300'"
              fill="currentColor" 
              viewBox="0 0 20 20">
              <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z"></path>
            </svg>
            <span class="text-sm text-gray-600 ml-1">{{ recipe.averageRating }}</span>
            <span class="text-xs text-gray-400">({{ recipe.ratingCount }})</span>
          </div>
        </div>

        <!-- Author -->
        <div class="flex items-center gap-2 pt-4 border-t border-gray-100">
          <img [src]="recipe.authorAvatar" [alt]="recipe.author" class="w-8 h-8 rounded-full">
          <span class="text-sm text-gray-600">{{ recipe.author }}</span>
        </div>
      </div>
    </div>
  </div>
</div>
